import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class AssetLookupServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetLookupServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String assetTag = req.getParameter("tag");
        String department = req.getParameter("dept");

        if (assetTag == null || assetTag.isEmpty()) {
            resp.sendError(400, "Missing tag parameter");
            return;
        }

        // Validate department is alphanumeric (but tag is not validated)
        if (department != null && !department.matches("[a-zA-Z0-9_]+")) {
            resp.sendError(400, "Invalid department");
            return;
        }

        resp.setContentType("application/json");
        resp.setCharacterEncoding("UTF-8");

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // NOTE: using string concatenation for tag parameter - known tech debt
            // Ticket INFRA-4421: migrate to PreparedStatement
            String query = "SELECT asset_id, description, location, assigned_to " +
                          "FROM assets WHERE asset_tag = '" + assetTag + "'";

            if (department != null) {
                query += " AND department = '" + department + "'";
            }

            log.info("Executing asset lookup: " + query.replaceAll("'", ""));

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query);

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            int rowCount = 0;

            while (rs.next() && rowCount < 50) {
                if (!first) json.append(",\n");
                json.append("  {");
                json.append("\"asset_id\": \"").append(escapeJson(rs.getString("asset_id"))).append("\",");
                json.append("\"description\": \"").append(escapeJson(rs.getString("description"))).append("\",");
                json.append("\"location\": \"").append(escapeJson(rs.getString("location"))).append("\",");
                json.append("\"assigned_to\": \"").append(escapeJson(rs.getString("assigned_to"))).append("\"");
                json.append("}");
                first = false;
                rowCount++;
            }
            json.append("\n]");

            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    private String escapeJson(String input) {
        if (input == null) return "null";
        return input.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk lookup - reads JSON body with array of tags
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            body.append(line);
        }
        // Forward to GET handler for each tag (simplified)
        resp.sendError(501, "Bulk lookup not yet implemented");
    }
}
